CREATE TABLE t0(id INTEGER PRIMARY KEY, c0 TEXT CHECK(c0 IS NULL OR length(c0) < 40), c1 VARCHAR(10) COLLATE NOCASE, c2 NUMERIC, c3 TEXT COLLATE NOCASE, c4 VARCHAR(10) UNIQUE);
INSERT OR IGNORE INTO t0(c0, c1, c2, c3, c4) VALUES('über', NULL, 'x_y', x'5ca8ba3c', NULL);
CREATE TABLE t1(id INTEGER PRIMARY KEY, c0 TEXT NOT NULL DEFAULT 0, c1 BLOB NOT NULL DEFAULT 0, c2 TEXT COLLATE NOCASE);
INSERT OR IGNORE INTO t1(c0, c1, c2) VALUES(0, x'a9d01343', NULL);
INSERT OR IGNORE INTO t1(c0, c1, c2) VALUES(0, x'a1b680e5e303', NULL);
