SELECT length('x_y'), upper('x_y'), lower('x_y'), substr('x_y', 0, 4), instr('x_y', 'phi'), replace('x_y', 'é', '_'), trim('x_y'), ltrim('x_y', 'ab'), hex('x_y'), quote('x_y'), unicode('x_y'), 'x_y' LIKE 'a%', 'x_y' GLOB '*[a-m]*', char(82, 325), 'x_y' || 'phi', 'x_y' < 'phi', 'x_y' = 'phi' COLLATE NOCASE;
SELECT length('omega'), upper('omega'), lower('omega'), substr('omega', -1, 3), instr('omega', 'omicron'), replace('omega', 'e', 'XY'), trim('omega'), ltrim('omega', 'ab'), hex('omega'), quote('omega'), unicode('omega'), 'omega' LIKE '_', 'omega' GLOB '?', char(83, 599), 'omega' || 'omicron', 'omega' < 'omicron', 'omega' = 'omicron' COLLATE NOCASE;
