SELECT length('naïve'), upper('naïve'), lower('naïve'), substr('naïve', 3, 4), instr('naïve', 'kappa'), replace('naïve', 'é', ''), trim('naïve'), ltrim('naïve', 'ab'), hex('naïve'), quote('naïve'), unicode('naïve'), 'naïve' LIKE 'A%', 'naïve' GLOB '?', char(72, 213), 'naïve' || 'kappa', 'naïve' < 'kappa', 'naïve' = 'kappa' COLLATE NOCASE;
SELECT length('NULL'), upper('NULL'), lower('NULL'), substr('NULL', 2, 1), instr('NULL', 'x_y'), replace('NULL', 'e', 'XY'), trim('NULL'), ltrim('NULL', 'ab'), hex('NULL'), quote('NULL'), unicode('NULL'), 'NULL' LIKE '%a_', 'NULL' GLOB '*[a-m]*', char(82, 401), 'NULL' || 'x_y', 'NULL' < 'x_y', 'NULL' = 'x_y' COLLATE NOCASE;
